fetch("/pages/footer.html").then(function(e){if(!e.ok)throw new Error("Could not load footer: "+e.status);return e.text()}).then(function(e){e=e.replace('<span id="year"></span>',(new Date).getFullYear());const t=document.getElementById("footer-placeholder");t?t.outerHTML=e:document.body.insertAdjacentHTML("beforeend",e)}).catch(function(e){console.warn(e)});